// Writes src/races.gen.ts: the race models the game modes play (data/pools.json: the daily
// and survivor pools, plus versus mode's tracks), bundled into the Worker (Phase 4 spec A2). Races in no pool (validation
// only) stay out, which keeps the Worker small. CI checks the generated file is up to date.
//   pnpm --filter @boxthislap/worker races
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const races = join(here, '..', '..', '..', 'data', 'races');
const pools = JSON.parse(readFileSync(join(races, '..', 'pools.json'), 'utf8')) as {
  daily: string[];
  survivor: Record<string, number[]>;
};
// Versus mode's tracks run on these race files (packages/sim/src/versus.ts VERSUS_TRACKS).
const versus = ['italy-2024', 'belgium-2024', 'bahrain-2022', 'japan-2024', 'hungary-2025'];
const ids = [...new Set([...pools.daily, ...Object.keys(pools.survivor), ...versus])].sort();

const lines = [
  '// Generated by `pnpm --filter @boxthislap/worker races` from data/pools.json. Do not edit.',
  '',
  ...ids.map((id, i) => `import r${i} from '../../../data/races/${id}.json';`),
  '',
  'export const RACE_FILES: Record<string, unknown> = {',
  ...ids.map((id, i) => `  '${id}': r${i},`),
  '};',
  '',
];
writeFileSync(join(here, '..', 'src', 'races.gen.ts'), lines.join('\n'));
console.log(`bundled ${ids.length} races`);
